SELECT ?point ?lbl ?tsid WHERE {
  ?point ref:hasLabel ?lbl .
  FILTER(CONTAINS(?lbl, "SupplyFan"))
  OPTIONAL { ?point ref:hasTimeseriesId ?tsid }
}

SELECT ?point ?lbl ?pclass VALUES (?) WHERE {
  ?point a brick:Fan .
  ?point ref:hasLabel ?lbl .
  OPTIONAL { ?point rdf:type ?ptype }
}

SELECT ?point ?lbl ?cls WHERE {
  ?point a brick:Fan ;
         ref:hasLabel ?lbl .
  OPTIONAL { ?point rdf:type ?cls }
}

SELECT ?point ?lbl ?cls WHERE {
  ?point ref:hasLabel ?lbl .
  OPTIONAL { ?point rdf:type ?cls }
} LIMIT 50

